import json, sys
MODE = "adapt"
def decide(c):
  r, me, out, claimed = c["rules"], c["player"], [], set()
  for cell in sorted(c["cells"], key=lambda x:x["id"]):
    e=cell["energy"]+r["energyPerTick"]; ns=cell["neighbors"]
    enemies=sorted([n for n in ns if n["owner"] not in (None,me)],key=lambda n:(n.get("health",999),n["id"]))
    empty=sorted([n for n in ns if n["owner"] is None and n["id"] not in claimed],key=lambda n:n["id"])
    threatened=bool(enemies)
    if MODE in ("rush","hunt","focus") and enemies and e>=r["attackCost"]:
      target=enemies[0]; out.append({"sourceCell":cell["id"],"type":"attack","targetCell":target["id"],"power":r["maxAttackPower"]}); continue
    if MODE=="turtle" and threatened and e>=r["defendCost"]:
      out.append({"sourceCell":cell["id"],"type":"defend"}); continue
    if MODE=="bank" and e<r["maxEnergy"]: continue
    if MODE=="adapt" and threatened and e>=r["defendCost"]: out.append({"sourceCell":cell["id"],"type":"defend"}); continue
    if empty and e>=r["spreadCost"]:
      target=empty[0]; claimed.add(target["id"])
      out.append({"sourceCell":cell["id"],"type":"replicate" if MODE=="replicate" else "spread","targetCell":target["id"]}); continue
    if enemies and e>=r["attackCost"]:
      target=enemies[0]; out.append({"sourceCell":cell["id"],"type":"attack","targetCell":target["id"],"power":r["maxAttackPower"]})
  return {"apiVersion":"v1","actions":out}
json.dump(decide(json.load(sys.stdin)),sys.stdout)

