fun decide(context: Context): List<Action> = context.cells.map { cell ->
  val e=minOf(cell.energy+context.rules.energyPerTick,context.rules.maxEnergy)
  val enemy=cell.neighbors.filter { it.owner != null && it.owner != context.player }.minByOrNull { it.health }
  val empty=cell.neighbors.filter { it.owner == null }.minByOrNull { it.id }
  when { enemy != null && e >= context.rules.attackCost -> Action.Attack(cell.id,enemy.id,context.rules.maxAttackPower)
         empty != null && e >= context.rules.spreadCost -> Action.Spread(cell.id,empty.id)
         else -> Action.Idle(cell.id) }
}

